import { Suspense, ViewTransition } from "react";
import {
  GalleryContent,
  GalleryContentSkeleton,
} from "@/components/gallery-content";
import {
  GalleryControls,
  GalleryControlsSkeleton,
} from "@/components/gallery-controls";

export default function GalleryPage({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; sort?: string }>;
}) {
  return (
    <ViewTransition
      enter={{
        "nav-forward": "fade-in",
        "nav-back": "fade-in",
        default: "none",
      }}
      exit={{
        "nav-forward": "nav-forward",
        "nav-back": "nav-back",
        default: "none",
      }}
      default="none"
    >
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-12">
        <Suspense fallback={<GalleryControlsSkeleton />}>
          <GalleryControls />
        </Suspense>

        <Suspense
          fallback={
            <ViewTransition exit="slide-down" default="none">
              <GalleryContentSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="slide-up" default="none">
            <GalleryContent searchParams={searchParams} />
          </ViewTransition>
        </Suspense>
      </div>
    </ViewTransition>
  );
}

import { Suspense, ViewTransition } from "react";
import Link from "next/link";
import { getPhotos } from "@/data/queries/photos";
import { PhotoContent, PhotoContentSkeleton } from "./photo-content";

export async function generateStaticParams() {
  const photos = await getPhotos();
  return photos.map((photo) => ({ id: photo.id }));
}

export default async function PhotoPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;

  return (
    <ViewTransition
      enter={{
        "nav-forward": "nav-forward",
        "nav-back": "nav-back",
        default: "none",
      }}
      exit={{
        "nav-forward": "nav-forward",
        "nav-back": "nav-back",
        default: "none",
      }}
      default="none"
    >
      <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8 py-4 sm:py-10">
        <Link
          href="/"
          transitionTypes={["nav-back"]}
          className="inline-flex items-center gap-1.5 font-mono text-xs text-white/40 hover:text-white transition-colors mb-4 sm:mb-8"
          style={{ viewTransitionName: "gallery-back-link" }}
        >
          ← Gallery
        </Link>

        <Suspense
          fallback={
            <ViewTransition exit="slide-down" default="none">
              <PhotoContentSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="slide-up" default="none">
            <PhotoContent id={id} />
          </ViewTransition>
        </Suspense>
      </div>
    </ViewTransition>
  );
}

import { ViewTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import { getPhotoImage } from "@/lib/images";
import { getPhoto, getPhotos } from "@/data/queries/photos";
import { Badge } from "@/components/ui/badge";
import PhotoNavigationArrow from "./photo-navigation-arrow";

export async function PhotoContent({ id }: { id: string }) {
  const [photo, allPhotos] = await Promise.all([getPhoto(id), getPhotos()]);

  const currentIndex = allPhotos.findIndex((p) => p.id === id);
  const prevPhoto = currentIndex > 0 ? allPhotos[currentIndex - 1] : null;
  const nextPhoto =
    currentIndex < allPhotos.length - 1 ? allPhotos[currentIndex + 1] : null;

  return (
    <>
      <div className="relative mb-4 sm:mb-8">
        <div
          className="absolute left-0 top-1/2 -translate-y-1/2 z-10"
          style={{ viewTransitionName: "gallery-nav-prev" }}
        >
          <PhotoNavigationArrow photo={prevPhoto} mode="prev" />
        </div>

        <ViewTransition name={`photo-${photo.id}`} share="morph" default="none">
          <div
            className="relative mx-auto max-h-[45vh] md:max-h-[55vh] lg:max-h-[60vh] max-w-full overflow-hidden rounded-lg"
            style={{ aspectRatio: `${photo.w}/${photo.h}` }}
          >
            <Image
              data-photo-id={photo.id}
              src={getPhotoImage(photo.seed)}
              alt={`${photo.title} — ${photo.location}`}
              fill
              className="object-contain"
              priority
              sizes="(max-width: 1024px) 100vw, 80vw"
              placeholder="blur"
            />
          </div>
        </ViewTransition>

        <div
          className="absolute right-0 top-1/2 -translate-y-1/2 z-10"
          style={{ viewTransitionName: "gallery-nav-next" }}
        >
          <PhotoNavigationArrow photo={nextPhoto} mode="next" />
        </div>
      </div>

      <div>
        <div className="border-t border-white/10 pt-8">
          <div className="space-y-2">
            <h1 className="text-3xl font-semibold tracking-tight text-white">
              {photo.title}
            </h1>
            <p className="font-mono text-sm text-white/40">{photo.location}</p>
            <p className="text-sm text-white/60">
              {photo.photographer} &middot; {photo.year}
            </p>
            <div className="pt-1">
              <Link
                href={`/collection/${photo.collection}`}
                transitionTypes={["nav-forward"]}
              >
                <Badge variant="outline" className="font-mono text-xs">
                  {photo.photographer}
                </Badge>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export function PhotoContentSkeleton() {
  return (
    <>
      <div className="relative mb-4 sm:mb-8 animate-pulse">
        <div className="absolute left-0 top-1/2 -translate-y-1/2 z-10">
